use std::sync::Arc;
use crate::{blob_store::{BlobStore,BlobStoreError},reference::BlobRef};
pub trait BlobCodec<T>{fn encode(&self,v:&T)->Result<Vec<u8>,String>;fn decode(&self,b:&[u8])->Result<T,String>;fn blob_type(&self)->Option<&'static str>{None}}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct BlobMetadata{pub reference:BlobRef,pub kind:String,pub size_bytes:usize}
pub type BlobMetadataCallback=Arc<dyn Fn(BlobMetadata)+Send+Sync+'static>;
pub trait BlobMirror:Send+Sync{fn write_blob(&self,r:&BlobRef,b:&[u8])->Result<(),String>;}
pub struct TypedBlobStore<C>{store:BlobStore,codec:C,metadata:Option<BlobMetadataCallback>,mirror:Option<Arc<dyn BlobMirror>>}
impl<C>TypedBlobStore<C>{pub fn new(store:BlobStore,codec:C)->Self{Self{store,codec,metadata:None,mirror:None}}pub fn with_metadata_callback(mut self,f:impl Fn(BlobMetadata)+Send+Sync+'static)->Self{self.metadata=Some(Arc::new(f));self}pub fn with_cloud_mirror(mut self,m:Arc<dyn BlobMirror>)->Self{self.mirror=Some(m);self}pub fn get_encoded(&self,r:&BlobRef)->Result<Vec<u8>,String>{self.store.get(r).map_err(|e|e.to_string())}pub fn is_blob_durable(&self,r:&BlobRef)->Option<bool>{self.store.is_blob_durable(r)}pub fn flush(&self)->Result<(),String>{self.store.flush().map_err(|e|e.to_string())}pub fn decode_value<T>(&self,b:&[u8])->Result<T,String>where C:BlobCodec<T>{self.codec.decode(b)}pub fn encode_value<T>(&self,v:&T)->Result<Vec<u8>,String>where C:BlobCodec<T>{self.codec.encode(v)}pub fn get<T>(&self,r:&BlobRef)->Result<T,String>where C:BlobCodec<T>{self.decode_value(&self.get_encoded(r)?)}pub fn put<T>(&mut self,v:&T)->Result<BlobRef,String>where C:BlobCodec<T>{self.put_value(v).map(|(r,_)|r)}pub fn put_value<T>(&mut self,v:&T)->Result<(BlobRef,Vec<u8>),String>where C:BlobCodec<T>{let b=self.encode_value(v)?;let r=BlobRef::from_content(&b);self.put_encoded_with_reference::<T>(&r,&b,true)?;Ok((r,b))}pub fn put_encoded_with_reference<T>(&mut self,r:&BlobRef,b:&[u8],mirror:bool)->Result<(),String>where C:BlobCodec<T>{self.store.put_with_reference(r,b).map_err(|e:BlobStoreError|e.to_string())?;if let(Some(f),Some(kind))=(&self.metadata,self.codec.blob_type()){f(BlobMetadata{reference:r.clone(),kind:kind.into(),size_bytes:b.len()})}if mirror{if let Some(m)=&self.mirror{m.write_blob(r,b)?}else{self.store.flush().map_err(|e|e.to_string())?}}Ok(())}pub fn set_blob_readable_from_cloud_mirror<T>(&mut self,r:&BlobRef,b:&[u8])->Result<(),String>where C:BlobCodec<T>{self.put_encoded_with_reference::<T>(r,b,true)?;self.flush()}}
#[cfg(test)]mod tests{use super::*;use crate::{blob_store::BlobStore,serde::Utf8Codec};use std::sync::Mutex;struct Mirror(Mutex<Vec<Vec<u8>>>);impl BlobMirror for Mirror{fn write_blob(&self,_:&BlobRef,b:&[u8])->Result<(),String>{self.0.lock().unwrap().push(b.to_vec());Ok(())}}#[test]fn metadata_and_mirror_write_through(){let seen=Arc::new(Mutex::new(Vec::new()));let out=Arc::clone(&seen);let mirror=Arc::new(Mirror(Mutex::new(Vec::new())));let m:Arc<dyn BlobMirror>=mirror.clone();let mut s=TypedBlobStore::new(BlobStore::default(),Utf8Codec).with_metadata_callback(move|x|out.lock().unwrap().push(x)).with_cloud_mirror(m);let r=s.put(&"hello".to_string()).unwrap();assert_eq!(s.get::<String>(&r).unwrap(),"hello");assert_eq!(seen.lock().unwrap()[0].kind,"string");assert_eq!(mirror.0.lock().unwrap()[0],b"hello")}}
